--
-- Table structure for table `business_items`
--

DROP TABLE IF EXISTS `business_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `business_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类别',
  `project` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务项目',
  `parameter` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务参数',
  `unit_price` decimal(15,4) DEFAULT '0.0000' COMMENT '业务单价',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务单位',
  `settlement_fee` decimal(15,4) DEFAULT '0.0000' COMMENT '业务结算费',
  `performance_fee` decimal(15,4) DEFAULT '0.0000' COMMENT '业务绩效费',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2479 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='业务管理表';
/*!40101 SET character_set_client = @saved_cs_client */;

