--
-- Table structure for table `contracts`
--

DROP TABLE IF EXISTS `contracts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contracts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contract_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `date` date DEFAULT NULL COMMENT '日期',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同名称',
  `project_id` int DEFAULT NULL COMMENT '项目ID',
  `project_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `customer_id` int DEFAULT NULL COMMENT '客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `service_content` text COLLATE utf8mb4_unicode_ci COMMENT '服务内容',
  `amount` decimal(15,2) DEFAULT '0.00' COMMENT '合同金额',
  `receivable` decimal(15,2) DEFAULT '0.00' COMMENT '应收金额',
  `requested` decimal(15,2) DEFAULT '0.00' COMMENT '请款金额',
  `received` decimal(15,2) DEFAULT '0.00' COMMENT '收款金额',
  `labor_cost` decimal(15,2) DEFAULT '0.00' COMMENT '劳务费',
  `cost` decimal(15,2) DEFAULT '0.00' COMMENT '成本金额',
  `tax` decimal(15,2) DEFAULT '0.00' COMMENT '税费',
  `other` decimal(15,2) DEFAULT '0.00' COMMENT '其他',
  `business_fee` decimal(15,2) DEFAULT '0.00' COMMENT '业务费',
  `performance` decimal(15,2) DEFAULT '0.00' COMMENT '绩效',
  `profit` decimal(15,2) DEFAULT '0.00' COMMENT '利润',
  `manager` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人',
  `salesman_id` int DEFAULT NULL COMMENT '涓氬姟鍛業D',
  `salesman` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务员',
  `attachment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目附件',
  `dept_id` int DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门名称',
  `company_id` int DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `status` enum('待签订','进行中','已完成','已取消') COLLATE utf8mb4_unicode_ci DEFAULT '待签订' COMMENT '合同状态',
  `bank_account` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收款银行账号',
  `bank_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户行名称',
  `settlement_method` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结算方式',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `bank_account_id` int DEFAULT NULL COMMENT '银行账户ID',
  `bank_account_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contract_no` (`contract_no`),
  UNIQUE KEY `contract_no_2` (`contract_no`),
  UNIQUE KEY `contract_no_3` (`contract_no`),
  UNIQUE KEY `contract_no_4` (`contract_no`),
  UNIQUE KEY `contract_no_5` (`contract_no`),
  UNIQUE KEY `contract_no_6` (`contract_no`),
  UNIQUE KEY `contract_no_7` (`contract_no`),
  UNIQUE KEY `contract_no_8` (`contract_no`),
  UNIQUE KEY `contract_no_9` (`contract_no`),
  UNIQUE KEY `contract_no_10` (`contract_no`),
  UNIQUE KEY `contract_no_11` (`contract_no`),
  UNIQUE KEY `contract_no_12` (`contract_no`),
  UNIQUE KEY `contract_no_13` (`contract_no`),
  UNIQUE KEY `contract_no_14` (`contract_no`),
  UNIQUE KEY `contract_no_15` (`contract_no`),
  UNIQUE KEY `contract_no_16` (`contract_no`),
  UNIQUE KEY `contract_no_17` (`contract_no`),
  UNIQUE KEY `contract_no_18` (`contract_no`),
  UNIQUE KEY `contract_no_19` (`contract_no`),
  UNIQUE KEY `contract_no_20` (`contract_no`),
  UNIQUE KEY `contract_no_21` (`contract_no`),
  UNIQUE KEY `contract_no_22` (`contract_no`),
  UNIQUE KEY `contract_no_23` (`contract_no`),
  UNIQUE KEY `contract_no_24` (`contract_no`),
  UNIQUE KEY `contract_no_25` (`contract_no`),
  UNIQUE KEY `contract_no_26` (`contract_no`),
  UNIQUE KEY `contract_no_27` (`contract_no`),
  UNIQUE KEY `contract_no_28` (`contract_no`),
  KEY `bank_account_id` (`bank_account_id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_salesman_id` (`salesman_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_company_id` (`company_id`),
  KEY `idx_dept_id` (`dept_id`),
  KEY `idx_status` (`status`),
  KEY `idx_date` (`date`),
  CONSTRAINT `contracts_ibfk_517` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `contracts_ibfk_518` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `contracts_ibfk_519` FOREIGN KEY (`dept_id`) REFERENCES `departments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `contracts_ibfk_520` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `contracts_ibfk_521` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1738 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='合同表';
/*!40101 SET character_set_client = @saved_cs_client */;

