DROP TABLE IF EXISTS `customer_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customer_stats` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_id` int DEFAULT NULL COMMENT '客户ID',
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `date` date DEFAULT NULL COMMENT '统计日期',
  `contract_count` int DEFAULT '0' COMMENT '鍚堝悓鏁伴噺',
  `contract_amount` decimal(15,2) DEFAULT '0.00' COMMENT '合同金额',
  `receivable` decimal(15,2) DEFAULT '0.00' COMMENT '应收金额',
  `requested` decimal(15,2) DEFAULT '0.00' COMMENT '请款金额',
  `received` decimal(15,2) DEFAULT '0.00' COMMENT '收款金额',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8623 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户统计表';
