  `employee_id` int NOT NULL COMMENT '员工ID',
  `dept_id` int NOT NULL COMMENT '部门ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_dept` (`employee_id`,`dept_id`),
  UNIQUE KEY `employee_departments_employee_id_dept_id` (`employee_id`,`dept_id`),
