--
-- Table structure for table `finances`
--

DROP TABLE IF EXISTS `finances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `finances` (
  `id` int NOT NULL AUTO_INCREMENT,
  `finance_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '财务编号',
  `date` date DEFAULT NULL COMMENT '日期',
  `contract_id` int DEFAULT NULL COMMENT '合同ID',
  `contract_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `order_id` int DEFAULT NULL COMMENT '订单ID',
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单编号',
  `project_id` int DEFAULT NULL COMMENT '项目ID',
  `project_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '款项类别',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '内容描述',
  `type` enum('收入','支出') COLLATE utf8mb4_unicode_ci DEFAULT '收入' COMMENT '收支类别',
  `amount` decimal(15,2) DEFAULT '0.00' COMMENT '收支金额',
  `company_id` int DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `customer_id` int DEFAULT NULL COMMENT '客户ID',
  `booked` tinyint DEFAULT '0' COMMENT '是否入账 0否 1是',
  `invoice_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发票号',
  `attachment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件',
  `batch_id` int DEFAULT NULL COMMENT '璇锋?鎵规?ID',
  `batch_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '璇锋?鎵规?鍙',
  `receipt_id` int DEFAULT NULL COMMENT '鏀舵?璁板綍ID',
  `receipt_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鏀舵?缂栧彿',
  `account_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '璐︽埛绫诲瀷',
  `source_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源类型',
  `source_id` int DEFAULT NULL COMMENT '来源ID',
  `company_bank_account` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司银行账号快照',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `customer_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称（付款方）',
  `bank_account_id` int DEFAULT NULL COMMENT '银行账户ID',
  `bank_account_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行账户名称',
  PRIMARY KEY (`id`),
  UNIQUE KEY `finance_no` (`finance_no`),
  UNIQUE KEY `finance_no_2` (`finance_no`),
  UNIQUE KEY `finance_no_3` (`finance_no`),
  UNIQUE KEY `finance_no_4` (`finance_no`),
  UNIQUE KEY `finance_no_5` (`finance_no`),
  UNIQUE KEY `finance_no_6` (`finance_no`),
  UNIQUE KEY `finance_no_7` (`finance_no`),
  UNIQUE KEY `finance_no_8` (`finance_no`),
  UNIQUE KEY `finance_no_9` (`finance_no`),
  UNIQUE KEY `finance_no_10` (`finance_no`),
  UNIQUE KEY `finance_no_11` (`finance_no`),
  UNIQUE KEY `finance_no_12` (`finance_no`),
  UNIQUE KEY `finance_no_13` (`finance_no`),
  UNIQUE KEY `finance_no_14` (`finance_no`),
  UNIQUE KEY `finance_no_15` (`finance_no`),
  UNIQUE KEY `finance_no_16` (`finance_no`),
  UNIQUE KEY `finance_no_17` (`finance_no`),
  UNIQUE KEY `finance_no_18` (`finance_no`),
  UNIQUE KEY `finance_no_19` (`finance_no`),
  UNIQUE KEY `finance_no_20` (`finance_no`),
  UNIQUE KEY `finance_no_21` (`finance_no`),
  UNIQUE KEY `finance_no_22` (`finance_no`),
  KEY `bank_account_id` (`bank_account_id`),
  KEY `idx_contract_id` (`contract_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_batch_id` (`batch_id`),
  KEY `idx_receipt_id` (`receipt_id`),
  KEY `idx_source` (`source_type`,`source_id`),
  KEY `idx_booked_type` (`booked`,`type`),
  KEY `idx_date` (`date`),
  KEY `idx_company_id` (`company_id`),
  CONSTRAINT `finances_ibfk_219` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `finances_ibfk_220` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `finances_ibfk_221` FOREIGN KEY (`bank_account_id`) REFERENCES `bank_accounts` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8682 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='财务表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `finances`
--

/*!40000 ALTER TABLE `finances` DISABLE KEYS */;
/*!40000 ALTER TABLE `finances` ENABLE KEYS */;

--
-- Table structure for table `order_items`
--

DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL COMMENT '订单ID',
  `business_id` int DEFAULT NULL COMMENT '业务ID',
  `business_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类别',
  `business_project` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务项目',
  `parameter` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务参数',
  `quantity` decimal(15,4) DEFAULT '0.0000' COMMENT '数量',
  `unit_price` decimal(15,4) DEFAULT '0.0000' COMMENT '单价',
  `total` decimal(15,2) DEFAULT '0.00' COMMENT '金额',
  `settlement_fee` decimal(15,2) DEFAULT '0.00' COMMENT '结算费',
  `performance_fee` decimal(15,2) DEFAULT '0.00' COMMENT '绩效费',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`),
  CONSTRAINT `order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=49968 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单明细表';
/*!40101 SET character_set_client = @saved_cs_client */;

