--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单编号',
  `date` date DEFAULT NULL COMMENT '日期',
  `contract_id` int DEFAULT NULL COMMENT '合同ID',
  `contract_no` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `project_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程名称',
  `customer_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名称',
  `business_id` int DEFAULT NULL COMMENT '业务ID',
  `business_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类别',
  `business_parameter` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务参数',
  `business_unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务单位',
  `quantity` decimal(15,4) DEFAULT '0.0000' COMMENT '业务数量',
  `unit_price` decimal(15,4) DEFAULT '0.0000' COMMENT '业务单价',
  `total` decimal(15,2) DEFAULT '0.00' COMMENT '业务合计',
  `report_date` date DEFAULT NULL COMMENT '报告日期',
  `report_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报告编号',
  `report_signed` tinyint DEFAULT '0' COMMENT '报告签收 0未签 1已签',
  `report_attachment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报告附件',
  `settlement_fee` decimal(15,2) DEFAULT '0.00' COMMENT '业务结算费',
  `performance_fee` decimal(15,2) DEFAULT '0.00' COMMENT '业务绩效费',
  `manager` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人',
  `salesman_id` int DEFAULT NULL COMMENT '业务员ID',
  `salesman` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务员',
  `dept_id` int DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门名称',
  `company_id` int DEFAULT NULL COMMENT '公司ID',
  `company_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司名称',
  `bank_account_id` int DEFAULT NULL COMMENT '银行账户ID',
  `bank_account_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行账户名称',
  `status` enum('待处理','进行中','已完成','已取消') COLLATE utf8mb4_unicode_ci DEFAULT '待处理' COMMENT '订单状态',
  `payment_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请收款状态',
  `requested_amount` decimal(15,2) DEFAULT '0.00' COMMENT '累计请款金额',
  `received_amount` decimal(15,2) DEFAULT '0.00' COMMENT '累计收款金额',
  `performance_amount` decimal(15,2) DEFAULT '0.00' COMMENT '累计绩效金额',
  `calc_version` int DEFAULT '1' COMMENT '计算版本',
  `is_dirty` tinyint DEFAULT '0' COMMENT '是否存在待处理差异',
  `dirty_reason` text COLLATE utf8mb4_unicode_ci COMMENT '宸?紓鍘熷洜璇存槑',
  `last_recalc_at` datetime DEFAULT NULL COMMENT '最近重算时间',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `perf_generated` tinyint DEFAULT '0' COMMENT '绩效已生成',
  `finance_generated` tinyint DEFAULT '0' COMMENT '财务已生成',
  `finance_booked` tinyint DEFAULT '0' COMMENT '财务已请款',
  `business_project` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务项目',
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no` (`order_no`),
  UNIQUE KEY `order_no_2` (`order_no`),
  UNIQUE KEY `order_no_3` (`order_no`),
  UNIQUE KEY `order_no_4` (`order_no`),
  UNIQUE KEY `order_no_5` (`order_no`),
  UNIQUE KEY `order_no_6` (`order_no`),
  UNIQUE KEY `order_no_7` (`order_no`),
  UNIQUE KEY `order_no_8` (`order_no`),
  UNIQUE KEY `order_no_9` (`order_no`),
  UNIQUE KEY `order_no_10` (`order_no`),
  UNIQUE KEY `order_no_11` (`order_no`),
  UNIQUE KEY `order_no_12` (`order_no`),
  UNIQUE KEY `order_no_13` (`order_no`),
  UNIQUE KEY `order_no_14` (`order_no`),
  UNIQUE KEY `order_no_15` (`order_no`),
  UNIQUE KEY `order_no_16` (`order_no`),
  UNIQUE KEY `order_no_17` (`order_no`),
  UNIQUE KEY `order_no_18` (`order_no`),
  UNIQUE KEY `order_no_19` (`order_no`),
  UNIQUE KEY `order_no_20` (`order_no`),
  UNIQUE KEY `order_no_21` (`order_no`),
  UNIQUE KEY `order_no_22` (`order_no`),
  UNIQUE KEY `order_no_23` (`order_no`),
  UNIQUE KEY `order_no_24` (`order_no`),
  UNIQUE KEY `order_no_25` (`order_no`),
  UNIQUE KEY `order_no_26` (`order_no`),
  UNIQUE KEY `order_no_27` (`order_no`),
  KEY `business_id` (`business_id`),
  KEY `idx_contract_id` (`contract_id`),
  KEY `idx_salesman_id` (`salesman_id`),
  KEY `idx_status` (`status`),
  KEY `idx_payment_status` (`payment_status`),
  KEY `idx_date` (`date`),
  KEY `idx_company_id` (`company_id`),
  KEY `idx_dept_id` (`dept_id`),
  CONSTRAINT `orders_ibfk_469` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `orders_ibfk_470` FOREIGN KEY (`business_id`) REFERENCES `business_items` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `orders_ibfk_471` FOREIGN KEY (`dept_id`) REFERENCES `departments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `orders_ibfk_472` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=37996 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单表';
