--
-- Table structure for table `payment_request_batches`
--

DROP TABLE IF EXISTS `payment_request_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_request_batches` (
  `id` int NOT NULL AUTO_INCREMENT,
  `batch_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '璇锋?鎵规?鍙',
  `date` date DEFAULT NULL COMMENT '璇锋?鏃ユ湡',
  `contract_id` int DEFAULT NULL COMMENT '鍚堝悓ID',
  `contract_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鍚堝悓缂栧彿',
  `project_id` int DEFAULT NULL COMMENT '椤圭洰ID',
  `project_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '椤圭洰鍚嶇О',
